part of 'model_analyzer.dart';

String _emitLibrary(
  Map<String, List<AnalyzedModel>> byFile, {
  required String outputPath,
  List<AnalyzedSeeder> seeders = const [],
}) {
  final paths = {
    ...byFile.keys,
    ...seeders.where((s) => s.hasRun).map((s) => s.path),
  }.toList()..sort();
  final all = byFile.values.expand((models) => models).toList();
  _resolveForeignKeys(all);
  final names = <AnalyzedModel, String>{};
  final b = StringBuffer(
    '// GENERATED BY TikalORM - DO NOT MODIFY BY HAND.\n// ignore_for_file: camel_case_types\n',
  );
  b.writeln("import 'package:tikal_orm/tikal_orm.dart' as orm;");
  final imports = <(String, String)>[];
  for (var i = 0; i < paths.length; i++) {
    final uri = Uri.file(
      p.relative(
        File(paths[i]).absolute.path,
        from: File(outputPath).absolute.parent.path,
      ),
    );
    imports.add((
      uri.toString(),
      'import ${_dartLiteral(uri.toString())} as m$i;',
    ));
    for (final model in byFile[paths[i]] ?? <AnalyzedModel>[]) {
      names[model] = 'm$i.${model.name}';
    }
  }
  imports.sort((a, b) {
    final length = a.$1.length.compareTo(b.$1.length);
    return length == 0 ? a.$1.compareTo(b.$1) : length;
  });
  if (imports.isNotEmpty) b.writeln('\n// Models');
  for (final entry in imports) {
    b.writeln(entry.$2);
  }
  b.writeln("\nexport 'package:tikal_orm/tikal_orm.dart' hide Tikal;");
  all.sort((a, b) => a.name.compareTo(b.name));
  for (final model in all) {
    b.writeln(_generateModel(model, names));
  }
  b.writeln(
    'final tikalModels = orm.ModelRegistry([${all.map((m) => '${m.name}_.table').join(', ')}]);',
  );
  b.writeln(
    const SeederAnalyzer().generateRegistry(seeders, {
      for (final (index, path) in paths.indexed) path: 'm$index',
    }),
  );
  b.writeln('''
/// Application entry point with the models discovered by generate/watch.
/// Configure explicitly; importing this file has no registration side effects.
abstract final class Tikal {
  static Future<void> configure({
    orm.DatabaseConfig? database,
    orm.TikalDatabase? connection,
    orm.ModelRegistry? models,
  }) => orm.Tikal.configure(
    database: database,
    connection: connection,
    models: models ?? tikalModels,
  );

  static orm.TikalDatabase get database => orm.Tikal.database;
  static const close = orm.Tikal.close;
  static const model = orm.Tikal.model;
  static const save = orm.Tikal.save;
  static const find = orm.Tikal.find;
  static const all = orm.Tikal.all;
  static const query = orm.Tikal.query;
  static const delete = orm.Tikal.delete;
  static const transaction = orm.Tikal.transaction;
}
''');
  return b.toString();
}

String _generateModel(AnalyzedModel model, Map<AnalyzedModel, String> names) {
  final name = names[model]!;
  final holder = '${model.name}_';
  const prefix = 'orm.';
  final b = StringBuffer('final class $holder {\n');
  for (final f in model.fields) {
    final c = f.column;
    final sqlType = c.type == 'uuid' ? 'uuid' : f.sqlType;
    final decoder = _decoderName(f);
    final decodeArg = decoder == null
        ? ''
        : 'decode: (row) => $prefix$decoder(row, ${_dartLiteral(c.name)}), ';
    b.writeln(
      'static final ${f.name} = ${prefix}ModelColumn<$name, ${f.valueType}>(name: ${_dartLiteral(c.name)}, sqlType: ${prefix}SqlType.$sqlType, read: (m) => m.${f.name}, write: (m, v) => m.${f.name} = v${f.nullable ? '' : '!'}, ${decodeArg}nullable: ${c.nullable}, primaryKey: ${c.primaryKey}, unique: ${c.unique}, autoIncrement: ${c.identity}, hasDefault: ${c.defaultSql != null || c.identity});',
    );
  }
  final fieldsByName = {for (final f in model.fields) f.name: f};
  final args = <String>[];
  for (final p in model.constructor.parameters.parameters.where(
    (p) => p.isRequired,
  )) {
    final f = fieldsByName[p.name!.lexeme]!;
    final decoder = _decoderName(f);
    final access = decoder == null
        ? 'row.as<${f.valueType}>(${_dartLiteral(f.column.name)})'
        : '$prefix$decoder(row, ${_dartLiteral(f.column.name)})';
    args.add(
      '${p.isNamed ? '${f.name}: ' : ''}$access${f.nullable ? '' : '!'}',
    );
  }
  final table = model.table;
  b.writeln(
    'static final table = ${prefix}TableDefinition<$name>(name: ${_dartLiteral(table.name)}, schema: ${_dartLiteral(table.schema ?? 'public')}, columns: [${model.fields.map((f) => f.name).join(', ')}], ${model.legacy ? '' : 'state: ${prefix}ModelState<$name>(), '}fromRowFactory: (row) => $name${model.constructor.name == null ? '' : '.${model.constructor.name!.lexeme}'}(${args.join(', ')}), create: ${_dartLiteral(table.createSql)},',
  );
  for (final f in model.fields) {
    if (f.createdAt) b.writeln('createdAtColumn: ${f.name},');
    if (f.updatedAt) b.writeln('updatedAtColumn: ${f.name},');
    if (f.deletedAt) b.writeln('deletedAtColumn: ${f.name},');
  }
  b.writeln(
    ');\nstatic ${prefix}Repository<$name> repository(${prefix}QueryExecutor executor) => ${prefix}Repository(executor: executor, definition: table);',
  );
  final helpers = <String, String>{
    'query':
        'static ${prefix}QueryBuilder<$name> query({${prefix}QueryExecutor? executor}) => repository(executor ?? ${prefix}Tikal.database).query();',
    'find':
        'static Future<$name?> find(Object id, {${prefix}QueryExecutor? executor, Duration? timeout}) => repository(executor ?? ${prefix}Tikal.database).findById(id, timeout: timeout);',
    'create':
        'static Future<$name> create($name model, {${prefix}QueryExecutor? executor, Duration? timeout}) => repository(executor ?? ${prefix}Tikal.database).insert(model, timeout: timeout);',
    'save':
        'static Future<$name> save($name model, {${prefix}QueryExecutor? executor, Duration? timeout}) => repository(executor ?? ${prefix}Tikal.database).save(model, timeout: timeout);',
    'delete':
        'static Future<bool> delete($name model, {${prefix}QueryExecutor? executor, Duration? timeout}) => repository(executor ?? ${prefix}Tikal.database).delete(model, timeout: timeout);',
  };
  for (final helper in helpers.entries) {
    // Existing column accessors retain their names if a helper would collide.
    if (!fieldsByName.containsKey(helper.key)) b.writeln(helper.value);
  }
  for (final f in model.fields.where((f) => f.referencedModel != null)) {
    final target = f.referencedModel!;
    final targetName = names[target]!;
    final key = target.fields.singleWhere((f) => f.column.primaryKey);
    final code =
        'static final ${f.name}Relation = ${prefix}BelongsToRelation<$name, $targetName, ${f.valueType}>(foreignKey: ${f.name}, targetKey: ${target.name}_.${key.name}, target: ${target.name}_.table);';
    b.writeln(code);
  }
  b.writeln('}');
  if (!model.legacy) {
    b.writeln(
      'extension ${model.name}Persistence on $name { bool get isPersisted => $holder.table.isPersisted(this); bool get isDirty => $holder.table.changedColumnNames(this).isNotEmpty; Set<String> changedColumnNames() => $holder.table.changedColumnNames(this); }',
    );
  }
  return b.toString();
}

String _dartLiteral(String value) => jsonEncode(value).replaceAll(r'$', r'\$');

/// Chooses the engine-neutral decoder for a field whose raw driver value would
/// otherwise differ between engines (SQLite stores booleans, dates and JSON as
/// ints/text). Returns `null` when the default `row.as<T>` is already correct.
///
/// JSON decoders are only emitted for the variance-safe `Map<String, Object?>`
/// and `List<Object?>` shapes, so generated code stays assignable to the field.
String? _decoderName(AnalyzedField field) => switch (field.sqlType) {
  'boolean' => 'decodeBool',
  'date' || 'timestamp' || 'timestamptz' => 'decodeDateTime',
  'numeric' => 'decodeDecimal',
  'jsonb' => switch (field.valueType) {
    'Map<String, Object?>' => 'decodeMap',
    'List<Object?>' => 'decodeList',
    _ => null,
  },
  _ => null,
};
